  <style>
    *{box-sizing:border-box}body{margin:0;min-height:100vh;background:#f2f6fa;color:#0b2545;font:600 16px 'Smooch Sans',Arial,sans-serif}.shell{display:grid;min-height:100vh;grid-template-columns:minmax(320px,43%) 1fr}.brand{display:flex;flex-direction:column;justify-content:space-between;background:radial-gradient(circle at 22% 16%,#174772 0,#0b2545 48%,#06172b 100%);padding:46px;color:#fff}.brand-head{display:flex;align-items:center;gap:11px;font-size:23px;font-weight:800}.brand-head img{width:37px;height:37px;border-radius:9px}.eyebrow{margin:0 0 16px;color:#9bd1fa;font:600 12px 'IBM Plex Mono',monospace;letter-spacing:.1em;text-transform:uppercase}.brand h1{max-width:440px;margin:0;font-size:48px;line-height:.98;letter-spacing:-.03em}.brand p{max-width:390px;margin:19px 0 0;color:#c7dcec;font-size:18px;line-height:1.4}.security{display:flex;align-items:center;gap:10px;color:#b9d4e8;font-size:14px}.security b{display:grid;width:27px;height:27px;place-items:center;border:1px solid rgba(183,220,244,.48);border-radius:50%;color:#fff}.content{display:grid;place-items:center;padding:32px}.card{width:min(100%,430px)}.card h2{margin:0;font-size:34px;letter-spacing:-.02em}.card>p{margin:7px 0 26px;color:#61778a;font-size:16px}.alert{margin:0 0 18px;border:1px solid #f3cccc;border-radius:10px;background:#fff3f3;padding:11px 13px;color:#9a3030;font-size:14px}.alert[hidden],.panel[hidden]{display:none}.field{display:block;margin:16px 0 0;color:#29465d;font-size:14px;font-weight:800}.input-wrap{position:relative;display:block;margin-top:7px}.field input{display:block;width:100%;height:49px;border:1px solid #c9d7e2;border-radius:8px;background:#fff;padding:0 48px;color:#0b2545;font:600 15px 'IBM Plex Mono',monospace;outline:none}.field input:focus{border-color:#0b2545;box-shadow:0 0 0 3px rgba(11,37,69,.1)}.field input::placeholder{color:#8da0af;opacity:1;font-family:'Smooch Sans',Arial,sans-serif;font-weight:600}.input-icon{position:absolute;top:50%;left:16px;width:18px;height:18px;transform:translateY(-50%);color:#61778a;pointer-events:none}.password-input{padding-right:52px!important}.password-toggle{position:absolute;top:50%;right:6px;display:grid;width:37px;height:37px;place-items:center;transform:translateY(-50%);border:0;border-radius:6px;background:transparent;color:#526d82;cursor:pointer}.password-toggle:hover,.password-toggle:focus-visible{background:#edf3f7;color:#0b2545;outline:none}.password-toggle svg{width:18px;height:18px}.button{display:flex;width:100%;height:50px;align-items:center;justify-content:center;gap:9px;margin-top:23px;border:0;border-radius:8px;background:#0b2545;color:#fff;font:800 16px 'Smooch Sans',Arial,sans-serif;cursor:pointer;transition:transform .16s ease,background .16s ease,opacity .16s ease}.button:hover{background:#123a63}.button:active{transform:scale(.985)}.button:disabled{opacity:.72;cursor:wait}.button.is-loading{pointer-events:none}.button-spinner{width:16px;height:16px;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;border-radius:50%;animation:button-spin .7s linear infinite}@keyframes button-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.button{transition:none}.button-spinner{animation:none}}.link-button{margin-top:17px;border:0;background:none;padding:0;color:#0b2545;font:800 14px 'Smooch Sans',Arial,sans-serif;cursor:pointer}.subtle{margin-top:21px;border-top:1px solid #dde7ee;padding-top:19px;color:#6c8192;font-size:13px;line-height:1.4}.setup-note{margin:0 0 17px;border:1px solid #c7dceb;border-radius:10px;background:#eff8ff;padding:11px 13px;color:#315673;font-size:14px;line-height:1.35}.back{margin-top:18px;color:#5d7588;font-size:14px}@media(max-width:760px){.shell{grid-template-columns:1fr}.brand{min-height:210px;padding:28px}.brand h1{font-size:36px}.brand p{font-size:16px}.security{display:none}.content{padding:37px 24px 48px}.card h2{font-size:31px}}
  </style>
</head>
<body>
  <main class="shell">
    <aside class="brand"><div><div class="brand-head"><img src="<?php echo htmlspecialchars($logoBase, ENT_QUOTES, 'UTF-8'); ?>/flowwithlit-icon-192.png" alt="">Flowwithlit</div><p class="eyebrow" style="margin-top:72px">Restricted operations</p><h1>Admin console</h1><p>Secure access for compliance, support, finance, and platform operations.</p></div><div class="security"><b>✓</b><span>Role-based access and audited administrator actions.</span></div></aside>
    <section class="content"><div class="card">
      <div id="alert" class="alert" hidden role="alert"></div>
      <section id="loginPanel" class="panel"><h2>Sign in</h2><p>Use your assigned administrator account.</p><form id="loginForm"><label class="field">Email address<span class="input-wrap"><i class="input-icon" data-lucide="mail" aria-hidden="true"></i><input id="email" type="email" autocomplete="username" placeholder="you@company.com" required></span></label><label class="field">Password<span class="input-wrap"><i class="input-icon" data-lucide="lock-keyhole" aria-hidden="true"></i><input id="password" class="password-input" type="password" autocomplete="current-password" placeholder="Enter your password" required><button class="password-toggle" type="button" data-password-toggle="password" aria-label="Show password"><i data-lucide="eye" aria-hidden="true"></i></button></span></label><button id="loginButton" class="button" type="submit">Sign in securely</button></form><button id="showBootstrap" class="link-button" type="button" hidden>Set up the first super administrator</button><p class="subtle">Only users listed in the dedicated administrator table can sign in here.</p></section>
      <section id="totpPanel" class="panel" hidden><h2>Verify your sign-in</h2><p>Enter the current six-digit code from your authenticator app.</p><form id="totpForm"><label class="field">Authenticator code<span class="input-wrap"><i class="input-icon" data-lucide="shield-check" aria-hidden="true"></i><input id="totpCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000" required></span></label><button id="totpButton" class="button" type="submit">Verify and continue</button></form><button id="backToLogin" class="link-button" type="button">Use another account</button></section>
      <section id="bootstrapPanel" class="panel" hidden><h2>First super admin</h2><p class="setup-note">This setup is available only until the first administrator is created. It then locks permanently.</p><form id="bootstrapForm"><label class="field">Full name<span class="input-wrap"><i class="input-icon" data-lucide="user-round" aria-hidden="true"></i><input id="setupName" autocomplete="name" placeholder="Your full name" required></span></label><label class="field">Work email<span class="input-wrap"><i class="input-icon" data-lucide="mail" aria-hidden="true"></i><input id="setupEmail" type="email" autocomplete="email" placeholder="you@company.com" required></span></label><label class="field">Password<span class="input-wrap"><i class="input-icon" data-lucide="lock-keyhole" aria-hidden="true"></i><input id="setupPassword" class="password-input" type="password" autocomplete="new-password" minlength="12" placeholder="At least 12 characters" required><button class="password-toggle" type="button" data-password-toggle="setupPassword" aria-label="Show password"><i data-lucide="eye" aria-hidden="true"></i></button></span></label><button id="bootstrapButton" class="button" type="submit">Create super admin</button></form><button id="backFromBootstrap" class="link-button" type="button">Back to sign in</button></section>
      <p class="back">← <a href="<?php echo htmlspecialchars($customerLoginUrl, ENT_QUOTES, 'UTF-8'); ?>">Return to customer sign in</a></p>
    </div></section>
  </main>
  <script src="https://unpkg.com/lucide@0.468.0/dist/umd/lucide.min.js"></script>
  <script>
    const $=id=>document.getElementById(id),panels=['loginPanel','totpPanel','bootstrapPanel'];let pendingToken='',pendingRole='';
    const adminApiBase=<?php echo json_encode($adminApiBase, JSON_UNESCAPED_SLASHES); ?>;
    const show=(id)=>panels.forEach(panel=>$(panel).hidden=panel!==id);const notice=(message='')=>{$('alert').textContent=message;$('alert').hidden=!message};
    const setBusy=(button,busy,label='Processing…')=>{if(busy){button.dataset.label=button.textContent.trim();button.disabled=true;button.classList.add('is-loading');button.setAttribute('aria-busy','true');button.innerHTML=`<span class="button-spinner" aria-hidden="true"></span>${label}`;return;}button.disabled=false;button.classList.remove('is-loading');button.removeAttribute('aria-busy');button.textContent=button.dataset.label||button.textContent;};
    const api=async(path,body,token)=>{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},body:JSON.stringify(body)});const data=await response.json().catch(()=>({error:'Unexpected server response.'}));if(!response.ok||!data.success)throw new Error(data.error||'Request failed.');return data};
    const enterConsole=(data)=>{localStorage.setItem('flow_admin_token',data.token);localStorage.setItem('flow_admin_role',data.role||'');window.location.replace('index.php')};
    fetch(`${adminApiBase}/bootstrap.php`,{headers:{Accept:'application/json'}}).then(response=>response.json()).then(status=>{if(status.success&&status.bootstrap_available)$('showBootstrap').hidden=false;}).catch(()=>{});
    $('loginForm').addEventListener('submit',async event=>{event.preventDefault();notice();const button=$('loginButton');setBusy(button,true,'Signing in…');try{const data=await api(`${adminApiBase}/login.php`,{email:$('email').value.trim(),password:$('password').value});if(data.requires_2fa){pendingToken=data.token;pendingRole=data.role;show('totpPanel');}else enterConsole(data);}catch(error){notice(error.message)}finally{setBusy(button,false)}});
    $('totpForm').addEventListener('submit',async event=>{event.preventDefault();notice();const button=$('totpButton');setBusy(button,true,'Verifying…');try{await api(`${adminApiBase}/totp-login.php`,{code:$('totpCode').value.trim()},pendingToken);enterConsole({token:pendingToken,role:pendingRole});}catch(error){notice(error.message)}finally{setBusy(button,false)}});
    $('bootstrapForm').addEventListener('submit',async event=>{event.preventDefault();notice();const button=$('bootstrapButton');setBusy(button,true,'Creating account…');try{const data=await api(`${adminApiBase}/bootstrap.php`,{full_name:$('setupName').value.trim(),email:$('setupEmail').value.trim(),password:$('setupPassword').value});enterConsole(data);}catch(error){notice(error.message)}finally{setBusy(button,false)}});
    $('showBootstrap').addEventListener('click',()=>{notice();show('bootstrapPanel')});$('backFromBootstrap').addEventListener('click',()=>show('loginPanel'));$('backToLogin').addEventListener('click',()=>{pendingToken='';show('loginPanel')});
    document.querySelectorAll('[data-password-toggle]').forEach(button=>button.addEventListener('click',()=>{const input=$(button.dataset.passwordToggle);const reveal=input.type==='password';input.type=reveal?'text':'password';button.setAttribute('aria-label',reveal?'Hide password':'Show password');button.innerHTML=`<i data-lucide="${reveal?'eye-off':'eye'}" aria-hidden="true"></i>`;window.lucide?.createIcons({attrs:{'aria-hidden':'true'}})}));
    window.lucide?.createIcons({attrs:{'aria-hidden':'true'}});
  </script>
</body></html>
